function infoCv_injectToCodex()
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addCategory', 'cv_cat', 'Cosmic Vault'%_t, 'data/textures/icons/crate.png')

    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addChapter', 'cv_cat', 'cv_cat_c0', 'API Framework'%_t)
    
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c0', 'cv_cat_a0', 'What is Cosmic Vault?'%_t, 'Cosmic Vault is the central API framework that powers the entire Cosmic Mod Series. It is primarily a modder\'s resource, providing a massive library of high-performance tools to build complex mechanics without tanking server TPS or causing multiplayer desyncs.\n\nWhile you won\'t see many direct gameplay features from Cosmic Vault itself, it is the beating heart that makes Cosmic War, Cosmic Overhaul, and Cosmic Ascendancy possible.'%_t, '')
    
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c0', 'cv_cat_a1', 'For Server Admins'%_t, 'Cosmic Vault gives the rest of the Cosmic series a couple of things to build on:\n\n- Highlander-Safe Shim Pattern: A documented coding convention (see MODDER_GUIDE.md) for wrapping vanilla script hooks instead of overwriting them outright, so multiple Cosmic mods - and other Workshop mods - can share the same vanilla file without one silently breaking the others.\n- Async Task Scheduler: Lets heavy sector loops run as coroutines that yield across multiple ticks instead of freezing the server on a single one.'%_t, '')
    
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c0', 'cv_cat_a2', 'For Mod Developers'%_t, 'If you are a modder looking to hook into the Cosmic series, you can safely leverage the Vault\'s APIs.\n\nRead the full MODDER_GUIDE.md located in the Cosmic Vault mod directory for documentation on:\n- Player Settings Storage\n- Faction Index Registry\n- Cinematic UI Components\n- The Async Scheduler\n- Complex Entity Data Serialization\n- Arsenal Generation\n- Dynamic Invasion Scaling (cosmicvaultscaling.lua)\n- Market Economies and Diplomatic Reputation Wrappers'%_t, '')

    -- Shared Utility APIs
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addChapter', 'cv_cat', 'cv_cat_c1', 'Shared Utility APIs'%_t)
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c1', 'cv_cat_a3', 'Galactic News & Dialogue API'%_t, 'Provides a unified framework for broadcasting global news events and managing complex, state-aware dialogue trees for NPCs without overriding vanilla dialogue files.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c1', 'cv_cat_a4', 'Player Settings & Config API'%_t, 'A robust wrapper for saving client UI preferences and Cosmic Configuration Menu (CCM) settings safely without causing file I/O locks.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c1', 'cv_cat_a5', 'Faction Index & Traits API'%_t, 'Tracks dynamic traits (Warmonger, Pacifist, etc) and identifies destroyed or dead empires across the galaxy safely.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c1', 'cv_cat_a6', 'Territory & Anomalies API'%_t, 'Allows mods to seamlessly expand borders, override sector ownership, and spawn persistent field anomalies - currently Precursor Wrecks and Spatial Rifts - for other Cosmic mods to build encounters and loot around.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c1', 'cv_cat_a7', 'Task Scheduler & Data Serialization'%_t, 'Provides standard coroutine wrappers to slice heavy tasks over multiple server ticks, alongside deep serializers to safely save complex nested Lua tables into entity data.'%_t, '')

    -- Vanilla+ Modding APIs
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addChapter', 'cv_cat', 'cv_cat_c2', 'Vanilla+ Modding APIs'%_t)
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a8', 'Arsenal & Goods API'%_t, 'Hooks to dynamically alter weapon properties, generate custom turrets, and inject new trade goods into the galaxy seamlessly.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a9', 'Economy & Mission API'%_t, 'Wrappers to inflict famine, trigger economic booms, and safely generate custom missions on the bulletin board.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a10', 'Encounter & Dynamic Scaling API'%_t, 'Standardized tools to spawn fleets that dynamically scale to match the player\'s current firepower and defensive rating.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a11', 'Buffs & Combat (DoT) API'%_t, 'Engine wrappers to apply permanent or temporary stat multipliers, weather immunities, and Damage-over-Time effects (like Dark Matter).'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a12', 'Blueprint & Station Interaction API'%_t, 'Hooks to spawn custom ships and stations natively from an XML block plan, and to inject extra interaction buttons into a station\'s UI without overriding its script wholesale.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a21', 'Fleet Command & AI Orders API'%_t, 'Safe injection of complex AI orders, such as patrol, escort, and automated mining or salvaging routes, without hard-overriding the vanilla craftorders.lua script.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a22', 'Subspace Weather Hazards API'%_t, 'A global weather system letting mods trigger or clear localized environmental hazards, like EMP storms and radiation fields, complete with native ship-problem warnings and protection checks for prepared ships.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c2', 'cv_cat_a23', 'Galaxy Event Timers'%_t, 'A server-safe timer system for tracking galaxy-wide events, such as Xsotan Invasions, that persist correctly across server reboots.'%_t, '')

    -- Gameplay Systems
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addChapter', 'cv_cat', 'cv_cat_c4', 'Gameplay Systems'%_t)
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c4', 'cv_cat_a16', 'Cosmic Configuration Menu (CCM) & Keybinds'%_t, 'Cosmic Vault provides a standalone, 3-column Configuration Menu that every other Cosmic mod plugs its settings and keybinds into.\n\nHotkeys fully support modifier keys (CTRL, ALT, SHIFT) and are automatically suppressed while you are typing in chat. You can cleanly unbind a key with Delete or Backspace instead of relying on Avorion\'s hardcoded Escape behavior, and every option has a one-click reset button to instantly restore its default value.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c4', 'cv_cat_a17', 'Faction Economy: Famine Scores'%_t, 'Cosmic Vault tracks a hidden Famine Score for every AI faction in the galaxy. Factions that lose territory or trade routes suffer rising famine, inflicting steep economic and military penalties the longer it goes unaddressed.\n\nOther Cosmic mods can read and react to this score to drive their own systems, such as forcing a starving faction into a desperate, all-or-nothing invasion.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c4', 'cv_cat_a18', 'Sector Anomalies'%_t, 'Beyond standard vanilla points of interest, Cosmic Vault can seed persistent, interactable anomalies out in the field, such as Precursor Wrecks and Spatial Rifts, for other Cosmic mods to build encounters and loot around.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c4', 'cv_cat_a19', 'Alliance Reputation Mirroring'%_t, 'Cosmic Vault mirrors faction relation changes to your active Player Alliance, so switching to a personal ship no longer lets you pick a fight without your alliance sharing the consequences.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c4', 'cv_cat_a20', 'Rift DLC Interoperability'%_t, 'If you are running Avorion\'s Into the Rift DLC, Cosmic Vault tracks a galaxy-wide Rift Guardian kill count and the number of successful Depth 50+ extractions.\n\nAs this global Escalation Level rises, vanilla Xsotan attack swarms grow more severe and gain an increased chance to converge on every online player simultaneously.'%_t, '')

    -- Synergies & Security
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addChapter', 'cv_cat', 'cv_cat_c3', 'Synergies & Security'%_t)
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c3', 'cv_cat_a13', 'Cosmic Series Synergy'%_t, 'Cosmic Vault acts as the communication bridge between Overhaul, Chronicles, War, and Ascendancy, allowing them to share state (like War Heat affecting Famine, or Faction Traits altering Dialogue) without explicitly depending on each other.'%_t, '')
    Player():invokeFunction('data/scripts/player/ui/cosmiccodex.lua', 'addArticle', 'cv_cat_c3', 'cv_cat_a14', 'Network Safety'%_t, 'Vault\'s own code sticks to the engine\'s seeded random() instead of math.random(), avoiding the desync-prone non-deterministic rolls that standard math.random() can produce in a multiplayer session. Its remote calls register through vanilla\'s own callable() mechanism like any other mod script.'%_t, '')

end
